<script setup lang="ts">import{computed}from"vue";import type{UsedFilterOption}from"@/domain/iptv/filterOptions";import type{PlaylistOption}from"@/domain/iptv/playlistOptions";const search=defineModel<string>("search",{required:true}),country=defineModel<string>("country",{required:true}),category=defineModel<string>("category",{required:true}),quality=defineModel<string>("quality",{required:true}),status=defineModel<string>("status",{required:true}),favorite=defineModel<string>("favorite",{required:true}),playlist=defineModel<string>("playlist",{default:""});const props=withDefaults(defineProps<{countries:UsedFilterOption[];categories:UsedFilterOption[];qualities:UsedFilterOption[];playlists?:PlaylistOption[];count:number}>(),{playlists:()=>[]});const emit=defineEmits<{clear:[]}>();const countries=computed(()=>props.countries.filter(x=>x.count>0)),categories=computed(()=>props.categories.filter(x=>x.count>0)),qualities=computed(()=>props.qualities.filter(x=>x.count>0));</script><template><section class="panel live-filters" aria-labelledby="live-filters-title"><div class="live-filter-header"><div><p class="eyebrow">Pesquisa avançada</p><h2 id="live-filters-title">Filtrar canais</h2></div><button v-if="count" class="button button-secondary" type="button" @click="emit('clear')">Limpar filtros ({{count}})</button></div><div class="live-filter-grid"><label class="form-field field-wide"><span>Pesquisar</span><input v-model.trim="search" type="search" placeholder="Nome, TVG-ID, EPG-ID ou playlist"/></label><label v-if="playlists.length" class="form-field"><span>Playlist</span><select v-model="playlist"><option value="">Todas</option><option v-for="x in playlists" :key="x.value" :value="x.value">{{x.label}} ({{x.count}})</option></select></label><label v-if="countries.length" class="form-field"><span>País</span><select v-model="country"><option value="">Todos</option><option v-for="x in countries" :key="x.value" :value="x.value">{{x.label}} ({{x.count}})</option></select></label><label v-if="categories.length" class="form-field"><span>Categoria</span><select v-model="category"><option value="">Todas</option><option v-for="x in categories" :key="x.value" :value="x.value">{{x.label}} ({{x.count}})</option></select></label><label v-if="qualities.length" class="form-field"><span>Qualidade</span><select v-model="quality"><option value="">Todas</option><option v-for="x in qualities" :key="x.value" :value="x.value">{{x.label}} ({{x.count}})</option></select></label><label class="form-field"><span>Estado</span><select v-model="status"><option value="">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select></label><label class="form-field"><span>Favoritos</span><select v-model="favorite"><option value="">Todos</option><option value="yes">Favoritos</option><option value="no">Não favoritos</option></select></label></div></section></template>
